def planet_in_sign(planet: str, sign: str) -> str:
    core, detail = PLANET_CORES[planet]
    return (f"{planet} governs {core} — {detail}. In {sign}, this is "
            f"{SIGN_EXPRESSIONS[sign]}.")


def planet_in_house(planet: str, house: int) -> str:
    title, _ = HOUSES[house]
    return (f"Placed in your {_ordinal(house)} house ({title}), it "
            f"{HOUSE_PLANET_NOTE[house]}.")


def _ordinal(n: int) -> str:
    return {1: "1st", 2: "2nd", 3: "3rd"}.get(n, f"{n}th")
